-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_POLICY_ENDORSEMENT
--   anchor      : HUB_POLICY
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Endorsement Number
--   feeders     : 3 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        null::varchar as ENDORSEMENT_NUMBER,
        null::varchar as ENDORSEMENT_TYPE,
        null::varchar as EFFECTIVE_DATE,
        'MAXI_HLTH_UWR_VW_DATA_BASIC_DETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_bd_apv') }}
    where HUB_POLICY_K0__EMIT
    union all
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        coalesce(nullif(trim(NUMBER),''),'') as ENDORSEMENT_NUMBER,
        TYPE_OF_ENDORSEMENT as ENDORSEMENT_TYPE,
        ENDORSEMENT_EFFECTIVE_DATE as EFFECTIVE_DATE,
        'MAXI_HLTH_UWR_VW_DATA_ENDORSEMENT_DETAILS' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_endorsement_dtl') }}
    where HUB_POLICY_K0__EMIT
    union all
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        coalesce(nullif(trim(ENDORSEMENT_NO),''),'') as ENDORSEMENT_NUMBER,
        ENDORSEMENT_TYPE as ENDORSEMENT_TYPE,
        EFFECTIVE_DATE as EFFECTIVE_DATE,
        'MAXI_HLTH_UWR_VW_DATA_ENDORSEMENT_HISTORY_REPORT' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_endorsement_history_report') }}
    where HUB_POLICY_K0__EMIT
)), hashed as (select *,
        case when ENDORSEMENT_TYPE is not null or EFFECTIVE_DATE is not null
             then md5(upper(coalesce(ENDORSEMENT_TYPE::varchar,'') || '||' || coalesce(EFFECTIVE_DATE::varchar,'')))
        end as SAT_POLICY_ENDORSEMENT_HASHDIFF
    from feeders)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_ENDORSEMENT_HASHDIFF is not null
  and ENDORSEMENT_NUMBER is not null
